"""Build small, verifiable AI briefs from local ASR JSON without an API call.

The full brief keeps every segment's exact start, end, and text. Word-level
timestamps remain in the source JSON and can be reopened for final alignment.
"""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
from typing import Any

FORMAT = "asr-brief-v1"


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def load_transcript(path: Path) -> tuple[bytes, dict[str, Any], list[tuple[Any, Any, str]]]:
    raw = path.read_bytes()
    document = json.loads(raw.decode("utf-8-sig"))
    if not isinstance(document, dict) or not isinstance(document.get("segments"), list):
        raise ValueError("전사 JSON에 segments 배열이 없습니다")
    rows = []
    for index, segment in enumerate(document["segments"]):
        if not isinstance(segment, dict):
            raise ValueError(f"segments[{index}]가 객체가 아닙니다")
        start, end, sentence = (segment.get(key) for key in ("start", "end", "text"))
        if (
            isinstance(start, bool) or isinstance(end, bool)
            or not isinstance(start, (int, float))
            or not isinstance(end, (int, float))
            or not isinstance(sentence, str)
            or start > end
        ):
            raise ValueError(f"segments[{index}]의 시각 또는 텍스트가 잘못됐습니다")
        rows.append((start, end, sentence))
    return raw, document, rows


def load_windows(path: Path, context: float) -> tuple[str, list[tuple[float, float]]]:
    if context < 0:
        raise ValueError("context는 0 이상이어야 합니다")
    raw = path.read_bytes()
    edits = json.loads(raw.decode("utf-8-sig"))
    if not isinstance(edits, list):
        raise ValueError("편집 JSON은 영상 객체의 배열이어야 합니다")
    windows = []
    for video in edits:
        for segment in video.get("segments", []):
            start, end = segment["start"], segment["end"]
            if not isinstance(start, (int, float)) or not isinstance(end, (int, float)) or start >= end:
                raise ValueError("편집 구간의 시작·끝이 잘못됐습니다")
            windows.append((max(0.0, start - context), end + context))
    if not windows:
        raise ValueError("편집 구간이 없습니다")
    windows.sort()
    merged = [windows[0]]
    for start, end in windows[1:]:
        if start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return sha256(raw), merged


def selected_indices(rows: list[tuple[Any, Any, str]], windows: list[tuple[float, float]] | None) -> list[int]:
    if windows is None:
        return list(range(len(rows)))
    return [
        index for index, (start, end, _) in enumerate(rows)
        if any(start <= right and end >= left for left, right in windows)
    ]


def make_brief(source: Path, edit: Path | None = None, context: float = 2.0) -> str:
    raw, document, rows = load_transcript(source)
    edit_hash, windows = load_windows(edit, context) if edit else (None, None)
    indices = selected_indices(rows, windows)
