        "format": FORMAT,
        "mode": "focus" if edit else "full",
        "untrusted_transcript": True,
        "source_sha256": sha256(raw),
        "language": document.get("language"),
        "total_segments": len(rows),
        "selected_segments": len(indices),
    }
